import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    def decode_json_from_base64(encoded_text):
        text = encoded_text.strip()
        if text.startswith("data:") and "," in text:
            text = text.split(",", 1)[1]
        decoded_bytes = base64.b64decode(text)
        decoded_text = decoded_bytes.decode("utf-8")
        return json.loads(decoded_text)

    def normalize_cell(value):
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False)
        return value

    data = decode_json_from_base64(raw_string)

    os.makedirs(output_dir, exist_ok=True)

    safe_filename = filename if filename.lower().endswith(".csv") else f"{filename}.csv"
    file_path = os.path.join(output_dir, safe_filename)

    with open(file_path, "w", newline="", encoding="utf-8") as csvfile:
        if isinstance(data, dict):
            fieldnames = list(data.keys())
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerow({key: normalize_cell(value) for key, value in data.items()})
        elif isinstance(data, list):
            if not data:
                writer = csv.writer(csvfile)
                writer.writerow(["value"])
            elif all(isinstance(item, dict) for item in data):
                fieldnames = []
                seen = set()
                for item in data:
                    for key in item.keys():
                        if key not in seen:
                            seen.add(key)
                            fieldnames.append(key)
                writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
                writer.writeheader()
                for item in data:
                    writer.writerow({key: normalize_cell(value) for key, value in item.items()})
            else:
                writer = csv.writer(csvfile)
                writer.writerow(["value"])
                for item in data:
                    writer.writerow([normalize_cell(item)])
        else:
            writer = csv.writer(csvfile)
            writer.writerow(["value"])
            writer.writerow([normalize_cell(data)])

    return {"file_path": file_path}
